// AI output disclosure for Aisty Free.

export const DISCLOSURE_LINE =
  "This content was generated by an AI system (Aisty). Review before relying on it.";

const withDisclosure = (text) => `${String(text ?? "").trimEnd()}\n\n${DISCLOSURE_LINE}\n`;

export async function copyWithCredential(text) {
  await navigator.clipboard.writeText(withDisclosure(text));
  return { flavours: ["text/plain"] };
}

export function downloadWithCredential(filename, content) {
  const blob = new Blob([withDisclosure(content)], { type: "text/markdown;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  document.body.appendChild(anchor);
  anchor.click();
  document.body.removeChild(anchor);
  // Revoking synchronously can cancel the download in Safari.
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  return { file: filename, sidecar: null };
}
